const fs = require('fs');
const path = require('path');

const projectRoot = process.env.PROJECT_ROOT || 'c:/Users/Paweł/Documents/GitHub/Money Printing Machine';
const outputDir = path.join(projectRoot, 'Output');

const brands = [];
